#!/usr/bin/env bash
# Check the in-progress Node refinement: generate Lean for the Node methods it
# covers, then elaborate Provium and each refinement module in order.
# Usage: build.sh <work-dir> [all | step-case ...]
# Step cases (vote, voted, prevote, replicated_none, ...) are generated by
# gen/step_cases.py from gen/step_proof_template.txt and gen/tail_<kind>.txt
# when present, where <kind> is the case name up to its first underscore.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../../.." && pwd)"
work="$(mkdir -p "$1" && cd "$1" && pwd)"
shift
toolchain="$(sed -n 's/^pub const TOOLCHAIN: &str = "\(.*\)";/\1/p' "$root/provium/src/project.rs")"
sed "s#@ROOT@#$root#g" "$here/generator.json" > "$work/project.json"
printf 'import Generated\nnamespace Placeholder\ntheorem t : Jarl.node_Node_step = Jarl.node_Node_step := rfl\nend Placeholder\n' \
  > "$work/Proofs.lean"
cargo run --quiet --locked --manifest-path "$root/provium/Cargo.toml" -- \
  verify-methods "$work/project.json" --out "$work/out"
ws="$work/ws"
mkdir -p "$ws/Provium"
cp "$root"/provium/lean/Provium/*.lean "$ws/Provium/"
cp "$work/out/Generated.lean" "$ws/"
cp "$root/jarl/proofs/election-safety/Model.lean" "$ws/"
cp "$here"/*.lean "$ws/"
check() {
  echo "== $1"
  (cd "$ws" && LEAN_PATH="$ws" elan run "$toolchain" lean --trust=0 --threads=1 -DwarningAsError=true \
    --memory=16384 "$1" -o "${1%.lean}.olean")
}
for m in State Semantics OrderStatistics Audit Loans ScalarSource ConstructorSource Imperative Footprint \
    Logic Wp ArrayMoves FieldReads RankArithmetic NumericFolds; do
  check "Provium/$m.lean"
done
for m in Generated Model Refine Abstract StepDefs Persist AbsStep; do
  check "$m.lean"
done
# `all` checks every step case and their combination `Step.lean`.
cases=("$@")
if [ "${1:-}" = all ]; then
  cases=(prevote prevoted vote voted append batch install replicated_none replicated_full replicated_conflict)
fi
for c in "${cases[@]}"; do
  tail="$here/gen/tail_${c%%_*}.txt"
  [ -f "$tail" ] || tail=-
  cp "$here/gen/step_proof_template.txt" "$ws/"
  python3 "$here/gen/step_cases.py" "$ws" "$c" "$tail"
  check "StepCase_$c.lean"
done
if [ "${1:-}" = all ]; then
  check Step.lean
fi
